CREATE TRIGGER center_delete_cleanup BEFORE DELETE ON centers BEGIN SELECT CASE WHEN OLD.active!=0 OR EXISTS(SELECT 1 FROM messages WHERE center_id=OLD.id AND state='submitting') THEN RAISE(ABORT,'CENTER_DELETE_BLOCKED') END; DELETE FROM auth_claims WHERE hash IN (SELECT hash FROM invitations WHERE center_id=OLD.id); DELETE FROM invitations WHERE center_id=OLD.id; DELETE FROM member_roles WHERE center_id=OLD.id; DELETE FROM roles WHERE center_id=OLD.id; DELETE FROM memberships WHERE center_id=OLD.id; DELETE FROM attempts WHERE center_id=OLD.id; DELETE FROM campaign_transitions WHERE campaign_id IN (SELECT id FROM campaigns WHERE center_id=OLD.id); DELETE FROM jobs WHERE center_id=OLD.id; DELETE FROM messages WHERE center_id=OLD.id; DELETE FROM campaign_exclusions WHERE center_id=OLD.id; UPDATE campaigns SET source_campaign_id=NULL WHERE center_id=OLD.id; DELETE FROM campaigns WHERE center_id=OLD.id; DELETE FROM balances WHERE center_id=OLD.id; DELETE FROM provider_configs WHERE center_id=OLD.id; DELETE FROM results WHERE center_id=OLD.id; DELETE FROM papers WHERE center_id=OLD.id; DELETE FROM participants WHERE center_id=OLD.id; DELETE FROM group_members WHERE center_id=OLD.id; DELETE FROM student_contacts WHERE center_id=OLD.id; DELETE FROM students WHERE center_id=OLD.id; DELETE FROM contacts WHERE center_id=OLD.id; DELETE FROM exams WHERE center_id=OLD.id; DELETE FROM catalog WHERE center_id=OLD.id; DELETE FROM templates WHERE center_id=OLD.id; END;
